using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.Diagnostics;using System.Reflection;using System.Runtime.Serialization;using System.Windows.Forms;using JouchoPet;
class ActionCheck {
 static int checks;static readonly string Folder=Path.Combine("qa","v0700");
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static void Quiet(bool ok,string name){if(!ok)throw new Exception(name);}
 static double Diff(int[] a,int[] b){double sum=0;for(int i=0;i<a.Length;i++)for(int s=0;s<32;s+=8)sum+=Math.Abs((int)((uint)a[i]>>s&255)-(int)((uint)b[i]>>s&255));return sum/(a.Length*4);}
 [STAThread]static void Main(){try{AnimationParameters.Load(Path.Combine(Folder,"baseline","animation-parameters.json"));Timing();Routes();Rendering();Interruption();Console.WriteLine("All "+checks+" action checks passed.");}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
 static Motion Ready(int facing){var m=new Motion();m.FollowPush(0,0,facing,300);return m;}
 static void Timing(){foreach(int fps in new[]{30,60,120})foreach(int facing in new[]{-1,1}) {
  var m=new ArcheryMotion();m.Request(facing);Check(m.Pending&&!m.Active,"archery waits for completed side turn / "+fps+" / "+facing);m.Begin(Ready(facing),true);int fired=0;
  for(int i=0;i<fps*7;i++){double prior=m.Age;if(m.Update(1.0/fps)){fired++;Quiet(prior<ArcheryMotion.ReleaseAt && m.Age>=ArcheryMotion.ReleaseAt,"release event wrong time");}double age=m.Age;m.Update(0);Quiet(m.Age==age,"zero dt advances bow");}
  Check(fired==1&&!m.Busy && m.Pose.Yaw==0 && m.Pose.Ready==0,"one shot then arms and turn return to rest / "+fps+" / "+facing);
 }
 var skipped=new ArcheryMotion();skipped.Request(1);skipped.Begin(Ready(1),true);Check(skipped.Update(10) && !skipped.Update(10),"large elapsed interval cannot duplicate or skip shot");
 Check(ArcheryMotion.At(.95,1).Ready==1 && ArcheryMotion.At(.9,1).Bow==0 && ArcheryMotion.At(1.55,1).Bow==1 && ArcheryMotion.At(.95,1).Reach==1 && ArcheryMotion.At(.95,1).Reach==1 && ArcheryMotion.At(.95,1).Arrow==0 && ArcheryMotion.At(1.4,1).Arrow==1,"lift and conjure finish together with fingers already on string");
 foreach(var screen in new[]{new Rectangle(0,0,1920,1080),new Rectangle(-1920,-200,1920,1080)})foreach(int facing in new[]{-1,1})foreach(int size in new[]{220,300,400})foreach(Point offset in new[]{new Point(30,800),new Point(960,800),new Point(1890,800),new Point(700,30)}) {
  PointF origin=new PointF(screen.Left+offset.X,screen.Top+offset.Y);var arrow=new MagicArrow(origin,facing,screen,size);PointF last=arrow.Tip;
  for(int i=0;i<100 && arrow.Age<arrow.FlightTime;i++){arrow.Update(1.0/120);PointF tip=arrow.Tip;Quiet(Math.Abs(Math.Abs(tip.X-origin.X)*Math.Tan(25*Math.PI/180)-Math.Abs(tip.Y-origin.Y))<.001,"trajectory is not 25 degrees");Quiet(RigParts.Length(last,tip)<=size*12.8/120+.001,"arrow teleport");last=tip;}
  arrow.Update(100);Quiet(Math.Abs(arrow.Impact.X-screen.Left)<.001 || Math.Abs(arrow.Impact.X-screen.Right)<.001 || Math.Abs(arrow.Impact.Y-screen.Top)<.001,"impact is not screen edge");Quiet(arrow.Done && arrow.RingOpacity==0 && Math.Abs(arrow.Radius-size*.75)<1e-8,"ring final radius/opacity wrong");
 }Check(true,"25-degree continuous arrows and three-quarter-height expanding rings on positive/negative monitor bounds");
 var ring=new MagicArrow(new PointF(500,500),1,new Rectangle(0,0,1000,800),300);ring.Update(ring.FlightTime);double radius=0,alpha=1;for(int i=0;i<40;i++){ring.Update(MagicArrow.RingDuration/40);Quiet(ring.Radius>=radius && ring.RingOpacity<=alpha,"ring reverses or brightens");radius=ring.Radius;alpha=ring.RingOpacity;}Check(true,"ring continuously expands and fades");
 }
 static void Routes(){foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1})foreach(int dy in new[]{-180,-2,2,180})foreach(bool run in new[]{false,true}) {
  Size canvas=PetRenderer.CanvasSize(size);Rectangle area=new Rectangle(-100,0,1900,1100);Point start=new Point(700,350),contact=new Point(900,350+dy);var plan=ApproachLeap.Plan(start,contact,area,canvas,size,facing,run);
  Quiet(plan!=null && plan.Vertical==Math.Sign(dy) && plan.Launch.Y==start.Y && plan.Landing.Y==contact.Y,"height approach missing or reversed");
  int expected=Math.Max(1,(int)Math.Round(size*(dy<0?AnimationParameters.Get("leapUpForward")/100:.28)*Math.Min(1,Math.Abs(dy)/(size*.55))));Quiet(Math.Abs(plan.Landing.X-plan.Launch.X)==expected,"lost configured forward movement");
  var original=new LeapMotion();original.Request(Math.Sign(dy),plan.Facing);original.Begin(plan.Launch,area,canvas,size,plan.Facing);
  PointF last=plan.At(0);for(int i=0;i<=Math.Ceiling(plan.Duration*60);i++){double age=Math.Min(plan.Duration,i/60.0);PointF p=plan.At(age);Quiet(area.Contains(new Rectangle(Point.Round(p),canvas)),"approach leaves work area");Quiet(RigParts.Length(last,p)<size*.08,"approach jumps between frames");LeapPose a=plan.Pose(age),b=LeapMotion.At(age,Math.Sign(dy));Quiet(a.Crouch==b.Crouch && a.Air==b.Air && a.Hair==b.Hair && a.Reach==b.Reach,"approach differs from existing jump/drop pose");last=p;}
  Quiet(Point.Round(last)==plan.Landing && Point.Round(plan.At(-1))==plan.Launch,"approach endpoints incorrect");
  var actual=plan.FromActual(new Point(plan.Launch.X+3,plan.Launch.Y),area,canvas,size);Quiet(actual.Launch.X==plan.Launch.X+3 && actual.Landing.X==plan.Landing.X+3,"braking caused position snap");
  if(run)Quiet((contact.X-plan.Landing.X)*facing>size*.17,"running pickup lacks approach runway");
 }Check(true,"48 up/down approach routes retain forward component, poses, runway and continuous endpoints");
 foreach(int facing in new[]{-1,1})foreach(int x in new[]{0,553})foreach(int dy in new[]{-180,180}){var p=ApproachLeap.Plan(new Point(270,270),new Point(x,270+dy),new Rectangle(0,0,900,900),PetRenderer.CanvasSize(300),300,facing,false);for(int i=0;i<200;i++)Quiet(new Rectangle(0,0,900,900).Contains(new Rectangle(Point.Round(p.At(i*.02)),PetRenderer.CanvasSize(300))),"edge route leaves area");Quiet(Math.Abs(p.Landing.X-p.Launch.X)>=83,"edge staging loses forward component");}Check(true,"edge approach stages from the available side without losing horizontal motion");
 Check(ApproachLeap.Plan(Point.Empty,Point.Empty,new Rectangle(0,0,1000,800),PetRenderer.CanvasSize(300),300,1,false)==null,"no unnecessary jump at matching height");
 }
 static void Rendering(){foreach(int size in new[]{220,300,400})using(var renderer=new PetRenderer()) {
  renderer.Resize(size);double ms=0;int n=0;foreach(int facing in new[]{-1,1}){
   int[] previous=null;double max=0;for(int i=0;i<=360;i++){var frame=new RenderFrame{Time=0,MotionState="idle",Archery=true,BowPose=ArcheryMotion.At(i/60.0,facing)};var sw=Stopwatch.StartNew();int[] pixels=PoseMesh.Read(renderer.Draw(frame));sw.Stop();ms+=sw.Elapsed.TotalMilliseconds;n++;Quiet(renderer.LastArcheryJacobian>0,"archery skin folded");if(previous!=null)max=Math.Max(max,Diff(previous,pixels));previous=pixels;}
   Console.WriteLine("Bow "+size+" / "+facing+" maximum 60 Hz channel delta="+max.ToString("F3"));Check(max<3,"bow has no pose replacement jump / "+size+" / "+facing);
   foreach(double boundary in new[]{.15,.9,.95,1.2,1.55,.95,1.15,1.4,1.5,1.63,2.1,2.5,2.55,2.64,2.77,3.1,3.15,4.65,4.85}){var f=new RenderFrame{MotionState="idle",Archery=true,BowPose=ArcheryMotion.At(Math.Max(0,boundary-1e-6),facing)};int[] before=PoseMesh.Read(renderer.Draw(f));f.BowPose=ArcheryMotion.At(boundary+1e-6,facing);Quiet(Diff(before,PoseMesh.Read(renderer.Draw(f)))<.3,"bow boundary discontinuity / "+boundary);}
   Check(true,"all bow stage joins continuous in either direction / "+size+" / "+facing);
  }Console.WriteLine("Full bow renderer "+size+": mean "+(ms/n).ToString("F2")+" ms (offscreen)");
 }
 using(var b=new Bitmap(900,650,PixelFormat.Format32bppPArgb))using(var g=Graphics.FromImage(b)){g.Clear(Color.Transparent);g.SmoothingMode=SmoothingMode.AntiAlias;ArcheryArt.Bow(g,new Point(200,150),347,300,ArcheryMotion.At(3.1,1));var arrow=new MagicArrow(new PointF(700,160),1,new Rectangle(0,0,900,650),300);arrow.Update(.1);ArcheryArt.Projectile(g,arrow);int visible=0;long red=0,green=0,blue=0;foreach(int pixel in PoseMesh.Read(b)){uint p=(uint)pixel,a=p>>24,r=p>>16&255,v=p>>8&255,u=p&255;Quiet(r<=a&&v<=a&&u<=a,"effect has invalid premultiplied color");if(a>0){visible++;red+=r;green+=v;blue+=u;}}/* Painted highlights can differ by one channel level. Check overall warm color while enforcing valid alpha on every pixel. */Check(visible>500&&red>=green&&green>blue,"bow, arrow and spiral contain warm-white and gold coverage");}
 }
 static void Interruption(){const BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;var pet=(Pet)FormatterServices.GetUninitializedObject(typeof(Pet));GC.SuppressFinalize(pet);Action<string,object> set=(n,v)=>typeof(Pet).GetField(n,flags).SetValue(pet,v);Func<string,object> get=n=>typeof(Pet).GetField(n,flags).GetValue(pet);
  var motion=new ArcheryMotion();motion.Request(1);motion.Begin(Ready(1),true);motion.Update(1.75);set("archery",motion);set("menuOpen",true);typeof(Pet).GetMethod("UpdateArchery",flags).Invoke(pet,new object[]{.05});Check(motion.Age==1.75,"opening menu freezes archery clock");
  set("magicArrow",new MagicArrow(new PointF(300,300),1,new Rectangle(0,0,1920,1080),300));typeof(Pet).GetMethod("CancelArchery",flags).Invoke(pet,null);Check(!motion.Busy && get("magicArrow")==null,"interruption clears bow and in-flight arrow");
  using(var menu=new ContextMenuStrip()){set("menu",menu);typeof(Pet).GetMethod("AddArcheryMenu",flags).Invoke(pet,null);Check(menu.Items.Count==1 && ((ToolStripMenuItem)menu.Items[0]).DropDownItems.Count==3,"left/right/random shot menu available");}
  using(var status=new ToolStripMenuItem()){set("carryStatus",status);set("carryPhase","heightjump");set("carryApproachLeap",AnimationDebugWindow.ApproachPreviewPlan(-1,1));set("carryAge",.6);set("carryLayout",IconPositions.Layout());set("rest",new RestMotion());set("motion",new Motion());typeof(Pet).GetMethod("CarryDesired",flags).Invoke(pet,new object[]{.05});typeof(Pet).GetMethod("CarryAfterMove",flags).Invoke(pet,new object[]{.05});Check((double)get("carryAge")==.6,"menu freezes approach jump before file pickup");typeof(Pet).GetMethod("CancelCarry",flags).Invoke(pet,new object[]{"test"});Check(get("carryApproachLeap")==null && (string)get("carryPhase")=="","cancel clears approach route");}
  using(var overlay=new MagicOverlay()){Quiet((bool)typeof(MagicOverlay).GetProperty("ShowWithoutActivation",flags).GetValue(overlay,null),"effect takes focus");var p=(CreateParams)typeof(MagicOverlay).GetProperty("CreateParams",flags).GetValue(overlay,null);Check((p.ExStyle&0x08000020)==0x08000020,"effect overlay is non-activating and click-through");overlay.PaintEffect(Point.Empty,347,300,null,null,true);Check(!overlay.Visible,"empty overlay remains hidden");}
 }
 static void Previews(){using(var renderer=new PetRenderer())using(var stage=new Bitmap(900,650)) {
  renderer.Resize(300);foreach(int facing in new[]{-1,1})using(var atlas=new Bitmap(360*15,260*27))using(var ag=Graphics.FromImage(atlas))using(var contact=new Bitmap(450*4,325*3))using(var cg=Graphics.FromImage(contact)){
   ag.Clear(Color.FromArgb(65,72,82));cg.Clear(Color.FromArgb(65,72,82));for(int i=0;i<396;i++){using(var g=Graphics.FromImage(stage)){g.Clear(Color.FromArgb(65,72,82));AnimationDebugWindow.DrawBowPreview(g,renderer,i/60.0,facing);}ag.DrawImage(stage,new Rectangle(i%15*360,i/15*260,360,260));}
   double[] times={0,.6,.40,.85,2.6,2.55,4.05,3.15,4.5,4.8,5.1,6};for(int i=0;i<times.Length;i++){using(var g=Graphics.FromImage(stage)){g.Clear(Color.FromArgb(65,72,82));AnimationDebugWindow.DrawBowPreview(g,renderer,times[i],facing);g.DrawString(times[i].ToString("F2")+" s",SystemFonts.DefaultFont,Brushes.White,20,20);}cg.DrawImage(stage,new Rectangle(i%4*450,i/4*325,450,325));}
   string name="archery-"+(facing<0?"left":"right");atlas.Save(Path.Combine(Folder,name+"-60fps.png"),ImageFormat.Png);contact.Save(Path.Combine(Folder,name+"-contact.png"),ImageFormat.Png);WritePreview(name,360,260,396,15);
  }
 }Check(true,"full left and right shot previews generated from actual renderer");}
 static void WritePreview(string name,int w,int h,int count,int columns){File.WriteAllText(Path.Combine(Folder,name+".html"),"<!doctype html><meta charset='utf-8'><title>白弓完整动作预览</title><style>body{background:#414852;color:white;text-align:center;font:18px system-ui}canvas{width:900px;max-width:100%;height:auto}button,select,input{margin:12px}</style><p>转向 · 凝弓 · 搭弦 · 凝箭 · 发射 · 触边圆环 · 收手</p><button onclick='play=!play'>播放 / 暂停</button><select id='speed'><option value='1'>正常速度</option><option value='.5'>半速</option><option value='.25'>四分之一速度</option></select><input id='seek' type='range' min='0' max='"+(count-1)+"' value='0'><br><canvas id='view' width='"+w+"' height='"+h+"'></canvas><script>let im=new Image(),ctx=view.getContext('2d'),play=true,f=0,last=0;im.src='"+name+"-60fps.png';seek.oninput=()=>{play=false;f=+seek.value};function tick(t){if(play&&last)f=(f+(t-last)*.06*+speed.value)%"+count+";last=t;let i=Math.floor(f);ctx.clearRect(0,0,"+w+","+h+");ctx.drawImage(im,i%"+columns+"*"+w+",Math.floor(i/"+columns+")*"+h+","+w+","+h+",0,0,"+w+","+h+");seek.value=i;requestAnimationFrame(tick)}im.onload=()=>requestAnimationFrame(tick)</script>");}
}
